pub(crate) fn update_lockfiles(
    config: &Config,
    ts: &Toolset,
    new_versions: &[ToolVersion],
    mode: LockfileUpdateMode,
) -> Result<bool> {
    if !Settings::get().lockfile_enabled() || (Settings::get().locked && !mode.allow_locked()) {
        return Ok(false);
    }

    let tools_by_source = tools_by_source_for_update(ts, new_versions);

    // Group config files by target lockfile path
    let mut lockfile_configs: HashMap<PathBuf, Vec<PathBuf>> = HashMap::new();
    for (config_path, cf) in config.config_files.iter().rev() {
        if !cf.source().is_mise_toml() {
            continue;
        }
        let (lockfile_path, _is_local) =
            lockfile_path_for_config(config_path, config.monorepo_lockfile_root().as_deref());
        lockfile_configs
            .entry(lockfile_path)
            .or_default()
            .push(config_path.clone());
    }
    for source in tools_by_source.keys() {
        if let Some((lockfile_path, _)) = lockfile_path_for_tool_source(config, source) {
            lockfile_configs.entry(lockfile_path).or_default();
        }
    }

    debug!("updating {} lockfiles", lockfile_configs.len());

    // Process each lockfile, deferring provenance errors until all lockfiles are saved.
    let mut provenance_errors: Vec<String> = Vec::new();
    let mut has_deferred_provenance = false;

    for (lockfile_path, configs) in lockfile_configs {
        // When lockfiles are enabled implicitly, only maintain files the user has
        // already created. An explicit `lockfile = true` opts into project
        // lockfile creation too; global lockfiles remain explicit via the
        // `mise lock --global` command.
        if !lockfile_path.exists() {
            let source_maps_to_lockfile = |source: &ToolSource| {
                lockfile_path_for_tool_source(config, source)
                    .is_some_and(|(path, _)| path == lockfile_path)
            };
            let updates_project_lockfiles = new_versions.is_empty()
                || new_versions.iter().any(|tv| {
                    tv.request
                        .source()
                        .path()
                        .is_some_and(|path| !crate::config::is_global_config(path))
                });
            let has_tool_contribution = updates_project_lockfiles
                && tools_by_source
                    .iter()
                    .any(|(source, tools)| !tools.is_empty() && source_maps_to_lockfile(source));
            let create_project_lockfile = config.lockfile_creation_enabled()
                && configs
                    .iter()
                    .any(|path| !crate::config::is_global_config(path))
                && has_tool_contribution;
            if !create_project_lockfile {
                continue;
            }
        }
        let is_monorepo_root_lockfile = config
            .monorepo_lockfile_root()
            .is_some_and(|root| lockfile_path.parent() == Some(root.as_path()));
        let _lock = crate::lock_file::LockFile::new(&lockfile_path)
            .with_callback(|l| debug!("waiting for lock on {}", display_path(l)))
            .lock()?;

        let mut existing_lockfile = Lockfile::read(&lockfile_path)
            .unwrap_or_else(|err| handle_lockfile_read_error(err, &lockfile_path));

        // Collect all tools from all contributing configs. This starts from the
        // resolved toolset, then overlays newly installed versions because a
        // fuzzy request may still resolve through the old lockfile entry until
        // this update is written.
        let mut tool_versions_by_short: HashMap<String, Vec<ToolVersion>> = HashMap::new();
        let mut contributing_sources = 0;

        for (source, tools) in &tools_by_source {
            let Some((source_lockfile, _)) = lockfile_path_for_tool_source(config, source) else {
                continue;
            };
            if source_lockfile == lockfile_path {
                contributing_sources += 1;
                for (short, versions) in tools {
                    tool_versions_by_short
                        .entry(short.clone())
                        .or_default()
                        .extend(versions.clone());
                }
            }
        }

        trace!(
            "updating lockfile {} from {} source(s)",
            display_path(&lockfile_path),
            contributing_sources
        );

        for new_version in new_versions {
            if let Some((source_lockfile, _)) =
                lockfile_path_for_tool_source(config, new_version.request.source())
            {
                if source_lockfile != lockfile_path {
                    continue;
                }

                let versions = tool_versions_by_short
                    .entry(new_version.short().to_string())
                    .or_default();
                versions.retain(|tv| {
                    tv.ba() != new_version.ba()
                        || tv.request.version() != new_version.request.version()
                        || tv.request.source() != new_version.request.source()
                });
                versions.push(new_version.clone());
            } else if let Some(versions) = tool_versions_by_short.get_mut(new_version.short()) {
                if let Some((idx, request)) = versions
                    .iter()
                    .enumerate()
                    .exactly_one()
                    .ok()
                    .map(|(idx, tv)| (idx, tv.request.clone()))
                {
                    // Only propagate when the new install resolves the same
                    // version specifier as the config. `mise x node` (no
                    // version) is rewritten by `with_default_to_latest` to
                    // carry the config's version string, so it matches and
                    // updates the lockfile as expected. `mise x node@latest`
                    // with mise.toml `node = "24"` carries a "latest"
                    // specifier that doesn't match — that's an ad-hoc CLI
                    // override and pairing the "24" request with a 25.x
                    // install would produce a nonsensical lockfile entry.
                    if new_version.request.version() != request.version() {
                        trace!(
                            "skipping lockfile update for {}@{} in {}: CLI override does not match config request {}",
                            new_version.short(),
                            new_version.version,
                            display_path(&lockfile_path),
                            request.version(),
                        );
                        continue;
                    }
                    let mut new_version = new_version.clone();
                    new_version.request = request;
                    versions.remove(idx);
                    versions.push(new_version);
                } else {
                    trace!(
                        "skipping lockfile update for {}@{} in {}: ambiguous config entries",
                        new_version.short(),
                        new_version.version,
                        display_path(&lockfile_path)
                    );
                }
            }
        }

        let tools_by_short: HashMap<String, Vec<LockfileTool>> = tool_versions_by_short
            .iter()
            .map(|(short, versions)| {
                Ok((
                    short.clone(),
                    versions
                        .iter()
                        .map(lockfile_tool_from_tool_version)
                        .collect::<Result<Vec<_>>>()?,
                ))
            })
            .collect::<Result<_>>()?;

        // Check for provenance regression before merging (which drops old version entries).
        // For github backend tools, error if the highest prior version had provenance but
        // the new version does not — this could indicate a supply chain attack.
        // Confirmed regressions are excluded from merge to preserve the old provenance entry.
        // Unverified upgrades (already-installed versions) instead preserve the prior
        // provenance entry as a baseline for the later auto-lock pass (see #11225).
        let ProvenanceRegressionCheck {
            regressing: regressing_tools,
            errors: regression_errors,
            deferred_baselines,
        } = check_provenance_regression(&existing_lockfile, &tools_by_short);
        has_deferred_provenance |= !deferred_baselines.is_empty();
        provenance_errors.extend(regression_errors);

        // Process each tool with deduplication, skipping regressing tools
        for (short, entries) in tools_by_short {
            if regressing_tools.contains(&short) {
                continue;
            }
            let versions = &tool_versions_by_short[&short];
            let bindings = entries
                .iter()
                .flat_map(|entry| {
                    entry.specifiers.iter().map(|specifier| {
                        (
                            specifier.clone(),
                            entry.version.clone(),
                            entry.options.clone(),
                        )
                    })
                })
                .collect_vec();
            // Normal monorepo installs load only the current config hierarchy,
            // not every sibling project. Consensus among those visible requests
            // is therefore not authoritative for the shared root lockfile. Fail
            // closed there and preserve legacy entries; ordinary lockfiles can
            // safely migrate when all requests for the file agree.
            let rekey_decisions = if is_monorepo_root_lockfile {
                RekeyDecisions::new()
            } else {
                build_rekey_decisions(versions, existing_lockfile.tools.get(&short))
            };
            let (mut merged_tools, consumed_keys) = merge_tool_entries(
                entries,
                existing_lockfile.tools.get(&short),
                |version, platform| {
                    rekey_decisions
                        .get(&(version.to_string(), platform.to_key()))
                        .cloned()
                        .flatten()
                },
            );

    if !all_provenance_errors.is_empty() {
        return Err(eyre!("{}", all_provenance_errors.join("\n")));
    }

    Ok(())
}

fn deferred_provenance_resolution_error(
    existing_tools: Option<&[LockfileTool]>,
    short: &str,
    version: &str,
    backend: &str,
    platform_key: &str,
    resolution_error: &str,
) -> Option<String> {
    find_provenance_regression_baseline(existing_tools, version, backend, platform_key, None)?;
    Some(format!(
        "could not verify provenance for {short}@{version} on \
         {platform_key}: {resolution_error}\nA prior version had provenance, so \
         mise refuses to lock this upgrade without verifying it. \
         Retry once the release source is reachable."
    ))
}

/// Result type for lock resolution tasks (shared by `mise lock` and auto-lock).
///
/// Fields: (short_name, version, backend_full, platform, info_or_error, options,
/// conda_packages, pkgx_packages, error_is_fatal).
/// The `info_or_error` field is `Ok(info)` on success or `Err(message)` on failure,
/// allowing callers to log at the appropriate level. `error_is_fatal` distinguishes
/// genuine conda solve failures from backends that use errors to skip unsupported targets.
pub(crate) type LockResolutionResult = (
    String,
    String,
    String,
    Platform,
    Result<PlatformInfo, String>,
    BTreeMap<String, String>,
    BTreeMap<String, CondaPackageInfo>,
    BTreeMap<String, PkgxPackageInfo>,
    bool,
);

/// Resolve lock info for a single tool/platform combination.
///
/// Returns a tuple of (short_name, version, backend_full, platform, info_or_error, options,
/// conda_packages, pkgx_packages, error_is_fatal).
/// Does not log errors — callers decide the appropriate log level.
pub(crate) async fn resolve_tool_lock_info(
    ba: crate::cli::args::BackendArg,
    tv: ToolVersion,
    platform: Platform,
    backend: Option<crate::backend::ABackend>,
) -> LockResolutionResult {
    let target = PlatformTarget::new(platform.clone());
    let error_is_fatal = backend
        .as_ref()
        .is_some_and(|backend| backend.get_type() == BackendType::Conda);

    let (info, options, conda_packages, pkgx_packages) = if let Some(backend) = backend {
        let options = match backend.resolve_lockfile_options(&tv.request, &target) {
            Ok(options) => options,
            Err(e) => {
                return (
                    ba.short.clone(),
                    tv.version.clone(),
                    ba.stored_full(),
                    platform,
                    Err(e.to_string()),
                    BTreeMap::new(),
                    BTreeMap::new(),
                    BTreeMap::new(),
                    error_is_fatal,
                );
            }
        };
        match crate::env::with_install_env(
            tv.install_env(),
            backend.resolve_lock_info(&tv, &target),
        )
        .await
        {
            Ok(info) => {
                let conda_packages = if backend.get_type() == BackendType::Conda {
                    let conda_backend = CondaBackend::from_arg(ba.clone());
                    match conda_backend.resolve_conda_packages(&tv, &target).await {
                        Ok(packages) => packages,
                        Err(e) => {
                            return (
                                ba.short.clone(),
                                tv.version.clone(),
                                ba.stored_full(),
                                platform,
                                Err(format!(
                                    "failed to resolve conda packages for {} on {}: {}",
                                    ba.short,
                                    target.to_key(),
                                    e
                                )),
                                options,
                                BTreeMap::new(),
                                BTreeMap::new(),
                                error_is_fatal,
                            );
                        }
                    }
                } else {
                    BTreeMap::new()
                };
                let pkgx_packages = if backend.get_type() == BackendType::Pkgx {
                    let pkgx_backend = PkgxBackend::from_arg(ba.clone());
                    match pkgx_backend.resolve_pkgx_packages(&tv, &target).await {
                        Ok(packages) => packages,
                        Err(e) => {
                            return (
                                ba.short.clone(),
                                tv.version.clone(),
                                ba.stored_full(),
                                platform,
                                Err(format!(
                                    "failed to resolve pkgx packages for {} on {}: {}",
                                    ba.short,
                                    target.to_key(),
                                    e
                                )),
                                options,
                                BTreeMap::new(),
                                BTreeMap::new(),
                                error_is_fatal,
                            );
                        }
                    }
                } else {
                    BTreeMap::new()
                };
                (Ok(info), options, conda_packages, pkgx_packages)
            }
            Err(e) => (
                Err(format!(
                    "failed to resolve {} for {}: {}",
                    ba.short,
                    platform.to_key(),
                    e
                )),
                options,
                BTreeMap::new(),
                BTreeMap::new(),
            ),
        }
    } else {
        (
            Err(format!("backend not found for {}", ba.short)),
            BTreeMap::new(),
            BTreeMap::new(),
            BTreeMap::new(),
        )
    };

    (
        ba.short.clone(),
        tv.version.clone(),
        ba.full(),
        platform,
        info,
        options,
        conda_packages,
        pkgx_packages,
        error_is_fatal,
    )
}

/// Apply a lock resolution result to a lockfile, updating platform info and conda packages.
/// Only applies data when the resolution succeeded (info is `Ok`).
///
/// Returns whether the resolution contributed any data. A backend that can't
/// resolve metadata without installing falls back to an empty `PlatformInfo`.
/// This still creates a tool/version entry when one does not exist, but it does
/// not overwrite an existing entry's platform metadata or count as a resolved
/// platform.
///
/// Returns an error if a github backend tool loses provenance on version upgrade,
/// which could indicate a supply chain attack.
pub(crate) fn apply_lock_result(
    lockfile: &mut Lockfile,
    result: LockResolutionResult,
) -> Result<bool> {
    let (
        short,
        version,
        backend,
        platform,
        info,
        options,
        conda_packages,
        pkgx_packages,
        _error_is_fatal,
    ) = result;
    let platform_key = platform.to_key();
    let mut applied = false;
    if let Ok(ref info) = info {
        if let Some(err) = check_single_tool_provenance(
            lockfile.tools.get(&short).map(Vec::as_slice),
            &short,
            &version,
            &backend,
            &platform_key,
            info.provenance.as_ref(),
        ) {
            return Err(eyre!("{err}"));
        }
        if info.is_empty() {
            let tool_exists = lockfile.tools.get(&short).is_some_and(|tools| {
                tools
                    .iter()
                    .any(|tool| tool.version == version && tool.options == options)
            });
            if !tool_exists {
                lockfile.set_platform_info(
                    &short,
                    &version,
                    Some(&backend),
                    &options,
                    &platform_key,
                    info.clone(),
                );
            }
        } else {
            applied = true;
            lockfile.set_platform_info(
                &short,
                &version,
                Some(&backend),
                &options,
                &platform_key,
                info.clone(),
            );
        }
    }
    for (basename, pkg_info) in conda_packages {
        applied = true;
        lockfile.set_conda_package(&platform_key, &basename, pkg_info);
    }
    for (id, pkg_info) in pkgx_packages {
        applied = true;
        lockfile.set_pkgx_package(&platform_key, &id, pkg_info);
    }
    Ok(applied)
}

type RekeyDecisions = HashMap<(String, String), Option<BTreeMap<String, String>>>;

fn record_rekey_decision(
    decisions: &mut RekeyDecisions,
    key: (String, String),
    resolved: Option<BTreeMap<String, String>>,
) {
    use std::collections::hash_map::Entry;

    match decisions.entry(key) {
        Entry::Vacant(entry) => {
            entry.insert(resolved);
        }
        Entry::Occupied(mut entry) if entry.get() != &resolved => {
            // Resolution errors and disagreement between same-version requests
            // both fail closed: leave the legacy platform where it is.
            entry.insert(None);
        }
        Entry::Occupied(_) => {}
    }
}

fn build_rekey_decisions(
    versions: &[ToolVersion],
    existing_tools: Option<&Vec<LockfileTool>>,
) -> RekeyDecisions {
    let legacy_platforms: HashMap<&str, BTreeSet<&str>> = existing_tools
        .into_iter()
        .flatten()
        .filter(|tool| tool.options.is_empty())
        .fold(HashMap::new(), |mut platforms, tool| {
            platforms
                .entry(tool.version.as_str())
                .or_default()
                .extend(tool.platforms.keys().map(String::as_str));
            platforms
        });
    let mut decisions = HashMap::new();

    for tv in versions {
        let Some(platforms) = legacy_platforms.get(tv.version.as_str()) else {
            continue;
        };
        for platform_key in platforms {
            let resolved = Platform::parse(platform_key).ok().and_then(|platform| {
                let backend = tv.request.backend().ok()?;

item.aggregated_output:
                .or_default()
                .entry(ba.short.to_string())
                .or_default()
                .push(tv.clone());
        }
    }

    // Add versions added within this session (from `mise use` or `mise up`),
    // replacing the resolved entry for the same request within that source.
    for new_tv in new_versions {
        let existing_versions = tools_by_source
            .entry(new_tv.request.source().clone())
            .or_default()
            .entry(new_tv.ba().short.to_string())
            .or_default();
        existing_versions.retain(|tv| tv.request.version() != new_tv.request.version());
        existing_versions.push(new_tv.clone());
    }

    tools_by_source
}

pub(crate) fn update_lockfiles(
    config: &Config,
    ts: &Toolset,
    new_versions: &[ToolVersion],
    mode: LockfileUpdateMode,
) -> Result<bool> {
    if !Settings::get().lockfile_enabled() || (Settings::get().locked && !mode.allow_locked()) {
        return Ok(false);
    }

    let tools_by_source = tools_by_source_for_update(ts, new_versions);

    // Group config files by target lockfile path
    let mut lockfile_configs: HashMap<PathBuf, Vec<PathBuf>> = HashMap::new();
    for (config_path, cf) in config.config_files.iter().rev() {
        if !cf.source().is_mise_toml() {
            continue;
        }
        let (lockfile_path, _is_local) =
            lockfile_path_for_config(config_path, config.monorepo_lockfile_root().as_deref());
        lockfile_configs
            .entry(lockfile_path)
            .or_default()
            .push(config_path.clone());
    }
    for source in tools_by_source.keys() {
        if let Some((lockfile_path, _)) = lockfile_path_for_tool_source(config, source) {
            lockfile_configs.entry(lockfile_path).or_default();
        }
    }

    debug!("updating {} lockfiles", lockfile_configs.len());

    // Process each lockfile, deferring provenance errors until all lockfiles are saved.
    let mut provenance_errors: Vec<String> = Vec::new();
    let mut has_deferred_provenance = false;

    for (lockfile_path, configs) in lockfile_configs {
        // When lockfiles are enabled implicitly, only maintain files the user has
        // already created. An explicit `lockfile = true` opts into project
        // lockfile creation too; global lockfiles remain explicit via the
        // `mise lock --global` command.
        if !lockfile_path.exists() {
            let source_maps_to_lockfile = |source: &ToolSource| {
                lockfile_path_for_tool_source(config, source)
                    .is_some_and(|(path, _)| path == lockfile_path)
            };
            let updates_project_lockfiles = new_versions.is_empty()
                || new_versions.iter().any(|tv| {
                    tv.request
                        .source()
                        .path()
                        .is_some_and(|path| !crate::config::is_global_config(path))
                });
            let has_tool_contribution = updates_project_lockfiles
                && tools_by_source
                    .iter()
                    .any(|(source, tools)| !tools.is_empty() && source_maps_to_lockfile(source));
            let create_project_lockfile = config.lockfile_creation_enabled()
                && configs
                    .iter()
                    .any(|path| !crate::config::is_global_config(path))
                && has_tool_contribution;
            if !create_project_lockfile {
                continue;
            }
        }
        let is_monorepo_root_lockfile = config
            .monorepo_lockfile_root()
            .is_some_and(|root| lockfile_path.parent() == Some(root.as_path()));
        let _lock = crate::lock_file::LockFile::new(&lockfile_path)
            .with_callback(|l| debug!("waiting for lock on {}", display_path(l)))
            .lock()?;

        let mut existing_lockfile = Lockfile::read(&lockfile_path)
            .unwrap_or_else(|err| handle_lockfile_read_error(err, &lockfile_path));

        // Collect all tools from all contributing configs. This starts from the
        // resolved toolset, then overlays newly installed versions because a
        // fuzzy request may still resolve through the old lockfile entry until
        // this update is written.
        let mut tool_versions_by_short: HashMap<String, Vec<ToolVersion>> = HashMap::new();
        let mut contributing_sources = 0;

        for (source, tools) in &tools_by_source {
            let Some((source_lockfile, _)) = lockfile_path_for_tool_source(config, source) else {
                continue;
            };
            if source_lockfile == lockfile_path {
                contributing_sources += 1;
                for (short, versions) in tools {
                    tool_versions_by_short
                        .entry(short.clone())
                        .or_default()
                        .extend(versions.clone());
                }
            }
        }

        trace!(
            "updating lockfile {} from {} source(s)",
            display_path(&lockfile_path),
            contributing_sources
        );

        for new_version in new_versions {
            if let Some((source_lockfile, _)) =
                lockfile_path_for_tool_source(config, new_version.request.source())
            {
                if source_lockfile != lockfile_path {
                    continue;
                }

                let versions = tool_versions_by_short
                    .entry(new_version.short().to_string())
                    .or_default();
                versions.retain(|tv| {
                    tv.ba() != new_version.ba()
                        || tv.request.version() != new_version.request.version()
                        || tv.request.source() != new_version.request.source()
                });
                versions.push(new_version.clone());
            } else if let Some(versions) = tool_versions_by_short.get_mut(new_version.short()) {
                if let Some((idx, request)) = versions
                    .iter()
                    .enumerate()
                    .exactly_one()
                    .ok()
                    .map(|(idx, tv)| (idx, tv.request.clone()))
                {
                    // Only propagate when the new install resolves the same
                    // version specifier as the config. `mise x node` (no
                    // version) is rewritten by `with_default_to_latest` to
                    // carry the config's version string, so it matches and
                    // updates the lockfile as expected. `mise x node@latest`
                    // with mise.toml `node = "24"` carries a "latest"
                    // specifier that doesn't match — that's an ad-hoc CLI
                    // override and pairing the "24" request with a 25.x
                    // install would produce a nonsensical lockfile entry.
                    if new_version.request.version() != request.version() {
                        trace!(
                            "skipping lockfile update for {}@{} in {}: CLI override does not match config request {}",
                            new_version.short(),
                            new_version.version,
                            display_path(&lockfile_path),
                            request.version(),
                        );
                        continue;
                    }
                    let mut new_version = new_version.clone();
                    new_version.request = request;
                    versions.remove(idx);
                    versions.push(new_version);
                } else {
                    trace!(
                        "skipping lockfile update for {}@{} in {}: ambiguous config entries",
                        new_version.short(),
                        new_version.version,
                        display_path(&lockfile_path)
                    );
                }
            }
        }

        let tools_by_short: HashMap<String, Vec<LockfileTool>> = tool_versions_by_short
            .iter()
            .map(|(short, versions)| {
                Ok((
                    short.clone(),
                    versions
                        .iter()
                        .map(lockfile_tool_from_tool_version)
                        .collect::<Result<Vec<_>>>()?,
                ))
            })
            .collect::<Result<_>>()?;

        // Check for provenance regression before merging (which drops old version entries).
        // For github backend tools, error if the highest prior version had provenance but
        // the new version does not — this could indicate a supply chain attack.
        // Confirmed regressions are excluded from merge to preserve the old provenance entry.
        // Unverified upgrades (already-installed versions) instead preserve the prior
        // provenance entry as a baseline for the later auto-lock pass (see #11225).
        let ProvenanceRegressionCheck {
            regressing: regressing_tools,
            errors: regression_errors,
            deferred_baselines,
        } = check_provenance_regression(&existing_lockfile, &tools_by_short);
        has_deferred_provenance |= !deferred_baselines.is_empty();
        provenance_errors.extend(regression_errors);

        // Process each tool with deduplication, skipping regressing tools
        for (short, entries) in tools_by_short {
            if regressing_tools.contains(&short) {
                continue;
            }
            let versions = &tool_versions_by_short[&short];
            let bindings = entries
                .iter()
                .flat_map(|entry| {
                    entry.specifiers.iter().map(|specifier| {
                        (
                            specifier.clone(),
                            entry.version.clone(),
                            entry.options.clone(),
                        )
                    })
                })
                .collect_vec();
            // Normal monorepo installs load only the current config hierarchy,
            // not every sibling project. Consensus among those visible requests
            // is therefore not authoritative for the shared root lockfile. Fail
            // closed there and preserve legacy entries; ordinary lockfiles can
            // safely migrate when all requests for the file agree.
            let rekey_decisions = if is_monorepo_root_lockfile {
                RekeyDecisions::new()
            } else {
                build_rekey_decisions(versions, existing_lockfile.tools.get(&short))
            };
            let (mut merged_tools, consumed_keys) = merge_tool_entries(
                entries,
                existing_lockfile.tools.get(&short),
                |version, platform| {
                    rekey_decisions
                        .get(&(version.to_string(), platform.to_key()))
                        .cloned()
                        .flatten()
                },
            );

    if !all_provenance_errors.is_empty() {
        return Err(eyre!("{}", all_provenance_errors.join("\n")));
    }

    Ok(())
}

fn deferred_provenance_resolution_error(
    existing_tools: Option<&[LockfileTool]>,
    short: &str,
    version: &str,
    backend: &str,
    platform_key: &str,
    resolution_error: &str,
) -> Option<String> {
    find_provenance_regression_baseline(existing_tools, version, backend, platform_key, None)?;
    Some(format!(
        "could not verify provenance for {short}@{version} on \
         {platform_key}: {resolution_error}\nA prior version had provenance, so \
         mise refuses to lock this upgrade without verifying it. \
         Retry once the release source is reachable."
    ))
}

/// Result type for lock resolution tasks (shared by `mise lock` and auto-lock).
///
/// Fields: (short_name, version, backend_full, platform, info_or_error, options,
/// conda_packages, pkgx_packages, error_is_fatal).
/// The `info_or_error` field is `Ok(info)` on success or `Err(message)` on failure,
/// allowing callers to log at the appropriate level. `error_is_fatal` distinguishes
/// genuine conda solve failures from backends that use errors to skip unsupported targets.
pub(crate) type LockResolutionResult = (
    String,
    String,
    String,
    Platform,
    Result<PlatformInfo, String>,
    BTreeMap<String, String>,
    BTreeMap<String, CondaPackageInfo>,
    BTreeMap<String, PkgxPackageInfo>,
    bool,
);

/// Resolve lock info for a single tool/platform combination.
///
/// Returns a tuple of (short_name, version, backend_full, platform, info_or_error, options,
/// conda_packages, pkgx_packages, error_is_fatal).
/// Does not log errors — callers decide the appropriate log level.
pub(crate) async fn resolve_tool_lock_info(
    ba: crate::cli::args::BackendArg,
    tv: ToolVersion,
    platform: Platform,
    backend: Option<crate::backend::ABackend>,
) -> LockResolutionResult {
    let target = PlatformTarget::new(platform.clone());
    let error_is_fatal = backend
        .as_ref()
        .is_some_and(|backend| backend.get_type() == BackendType::Conda);

    let (info, options, conda_packages, pkgx_packages) = if let Some(backend) = backend {
        let options = match backend.resolve_lockfile_options(&tv.request, &target) {
            Ok(options) => options,
            Err(e) => {
                return (
                    ba.short.clone(),
                    tv.version.clone(),
                    ba.stored_full(),
                    platform,
                    Err(e.to_string()),
                    BTreeMap::new(),
                    BTreeMap::new(),
                    BTreeMap::new(),
                    error_is_fatal,
                );
            }
        };
        match crate::env::with_install_env(
            tv.install_env(),
            backend.resolve_lock_info(&tv, &target),
        )
        .await
        {
            Ok(info) => {
                let conda_packages = if backend.get_type() == BackendType::Conda {
                    let conda_backend = CondaBackend::from_arg(ba.clone());
                    match conda_backend.resolve_conda_packages(&tv, &target).await {
                        Ok(packages) => packages,
                        Err(e) => {
                            return (
                                ba.short.clone(),
                                tv.version.clone(),
                                ba.stored_full(),
                                platform,
                                Err(format!(
                                    "failed to resolve conda packages for {} on {}: {}",
                                    ba.short,
                                    target.to_key(),
                                    e
                                )),
                                options,
                                BTreeMap::new(),
                                BTreeMap::new(),
                                error_is_fatal,
                            );
                        }
                    }
                } else {
                    BTreeMap::new()
                };
                let pkgx_packages = if backend.get_type() == BackendType::Pkgx {
                    let pkgx_backend = PkgxBackend::from_arg(ba.clone());
                    match pkgx_backend.resolve_pkgx_packages(&tv, &target).await {
                        Ok(packages) => packages,
                        Err(e) => {
                            return (
                                ba.short.clone(),
                                tv.version.clone(),
                                ba.stored_full(),
                                platform,
                                Err(format!(
                                    "failed to resolve pkgx packages for {} on {}: {}",
                                    ba.short,
                                    target.to_key(),
                                    e
                                )),
                                options,
                                BTreeMap::new(),
                                BTreeMap::new(),
                                error_is_fatal,
                            );
                        }
                    }
                } else {
                    BTreeMap::new()
                };
                (Ok(info), options, conda_packages, pkgx_packages)
            }
            Err(e) => (
                Err(format!(
                    "failed to resolve {} for {}: {}",
                    ba.short,
                    platform.to_key(),
                    e
                )),
                options,
                BTreeMap::new(),
                BTreeMap::new(),
            ),
        }
    } else {
        (
            Err(format!("backend not found for {}", ba.short)),
            BTreeMap::new(),
            BTreeMap::new(),
            BTreeMap::new(),
        )
    };

    (
        ba.short.clone(),
        tv.version.clone(),
        ba.full(),
        platform,
        info,
        options,
        conda_packages,
        pkgx_packages,
        error_is_fatal,
    )
}

/// Apply a lock resolution result to a lockfile, updating platform info and conda packages.
/// Only applies data when the resolution succeeded (info is `Ok`).
///
/// Returns whether the resolution contributed any data. A backend that can't
/// resolve metadata without installing falls back to an empty `PlatformInfo`.
/// This still creates a tool/version entry when one does not exist, but it does
/// not overwrite an existing entry's platform metadata or count as a resolved
/// platform.
///
/// Returns an error if a github backend tool loses provenance on version upgrade,
/// which could indicate a supply chain attack.
pub(crate) fn apply_lock_result(
    lockfile: &mut Lockfile,
    result: LockResolutionResult,
) -> Result<bool> {
    let (
        short,
        version,
        backend,
        platform,
        info,
        options,
        conda_packages,
        pkgx_packages,
        _error_is_fatal,
    ) = result;
    let platform_key = platform.to_key();
    let mut applied = false;
    if let Ok(ref info) = info {
        if let Some(err) = check_single_tool_provenance(
            lockfile.tools.get(&short).map(Vec::as_slice),
            &short,
            &version,
            &backend,
            &platform_key,
            info.provenance.as_ref(),
        ) {
            return Err(eyre!("{err}"));
        }
        if info.is_empty() {
            let tool_exists = lockfile.tools.get(&short).is_some_and(|tools| {
                tools
                    .iter()
                    .any(|tool| tool.version == version && tool.options == options)
            });
            if !tool_exists {
                lockfile.set_platform_info(
                    &short,
                    &version,
                    Some(&backend),
                    &options,
                    &platform_key,
                    info.clone(),
                );
            }
        } else {
            applied = true;
            lockfile.set_platform_info(
                &short,
                &version,
                Some(&backend),
                &options,
                &platform_key,
                info.clone(),
            );
        }
    }
    for (basename, pkg_info) in conda_packages {
        applied = true;
        lockfile.set_conda_package(&platform_key, &basename, pkg_info);
    }
    for (id, pkg_info) in pkgx_packages {
        applied = true;
        lockfile.set_pkgx_package(&platform_key, &id, pkg_info);
    }
    Ok(applied)
}

type RekeyDecisions = HashMap<(String, String), Option<BTreeMap<String, String>>>;

fn record_rekey_decision(
    decisions: &mut RekeyDecisions,
    key: (String, String),
    resolved: Option<BTreeMap<String, String>>,
) {
    use std::collections::hash_map::Entry;

    match decisions.entry(key) {
        Entry::Vacant(entry) => {
            entry.insert(resolved);
        }
        Entry::Occupied(mut entry) if entry.get() != &resolved => {
            // Resolution errors and disagreement between same-version requests
            // both fail closed: leave the legacy platform where it is.
            entry.insert(None);
        }
        Entry::Occupied(_) => {}
    }
}

fn build_rekey_decisions(
    versions: &[ToolVersion],
    existing_tools: Option<&Vec<LockfileTool>>,
) -> RekeyDecisions {
    let legacy_platforms: HashMap<&str, BTreeSet<&str>> = existing_tools
        .into_iter()
        .flatten()
        .filter(|tool| tool.options.is_empty())
        .fold(HashMap::new(), |mut platforms, tool| {
            platforms
                .entry(tool.version.as_str())
                .or_default()
                .extend(tool.platforms.keys().map(String::as_str));
            platforms
        });
    let mut decisions = HashMap::new();

    for tv in versions {
        let Some(platforms) = legacy_platforms.get(tv.version.as_str()) else {
            continue;
        };
        for platform_key in platforms {
            let resolved = Platform::parse(platform_key).ok().and_then(|platform| {
                let backend = tv.request.backend().ok()?;

item.formatted_output:
                .or_default()
                .entry(ba.short.to_string())
                .or_default()
                .push(tv.clone());
        }
    }

    // Add versions added within this session (from `mise use` or `mise up`),
    // replacing the resolved entry for the same request within that source.
    for new_tv in new_versions {
        let existing_versions = tools_by_source
            .entry(new_tv.request.source().clone())
            .or_default()
            .entry(new_tv.ba().short.to_string())
            .or_default();
        existing_versions.retain(|tv| tv.request.version() != new_tv.request.version());
        existing_versions.push(new_tv.clone());
    }

    tools_by_source
}

pub(crate) fn update_lockfiles(
    config: &Config,
    ts: &Toolset,
    new_versions: &[ToolVersion],
    mode: LockfileUpdateMode,
) -> Result<bool> {
    if !Settings::get().lockfile_enabled() || (Settings::get().locked && !mode.allow_locked()) {
        return Ok(false);
    }

    let tools_by_source = tools_by_source_for_update(ts, new_versions);

    // Group config files by target lockfile path
    let mut lockfile_configs: HashMap<PathBuf, Vec<PathBuf>> = HashMap::new();
    for (config_path, cf) in config.config_files.iter().rev() {
        if !cf.source().is_mise_toml() {
            continue;
        }
        let (lockfile_path, _is_local) =
            lockfile_path_for_config(config_path, config.monorepo_lockfile_root().as_deref());
        lockfile_configs
            .entry(lockfile_path)
            .or_default()
            .push(config_path.clone());
    }
    for source in tools_by_source.keys() {
        if let Some((lockfile_path, _)) = lockfile_path_for_tool_source(config, source) {
            lockfile_configs.entry(lockfile_path).or_default();
        }
    }

    debug!("updating {} lockfiles", lockfile_configs.len());

    // Process each lockfile, deferring provenance errors until all lockfiles are saved.
    let mut provenance_errors: Vec<String> = Vec::new();
    let mut has_deferred_provenance = false;

    for (lockfile_path, configs) in lockfile_configs {
        // When lockfiles are enabled implicitly, only maintain files the user has
        // already created. An explicit `lockfile = true` opts into project
        // lockfile creation too; global lockfiles remain explicit via the
        // `mise lock --global` command.
        if !lockfile_path.exists() {
            let source_maps_to_lockfile = |source: &ToolSource| {
                lockfile_path_for_tool_source(config, source)
                    .is_some_and(|(path, _)| path == lockfile_path)
            };
            let updates_project_lockfiles = new_versions.is_empty()
                || new_versions.iter().any(|tv| {
                    tv.request
                        .source()
                        .path()
                        .is_some_and(|path| !crate::config::is_global_config(path))
                });
            let has_tool_contribution = updates_project_lockfiles
                && tools_by_source
                    .iter()
                    .any(|(source, tools)| !tools.is_empty() && source_maps_to_lockfile(source));
            let create_project_lockfile = config.lockfile_creation_enabled()
                && configs
                    .iter()
                    .any(|path| !crate::config::is_global_config(path))
                && has_tool_contribution;
            if !create_project_lockfile {
                continue;
            }
        }
        let is_monorepo_root_lockfile = config
            .monorepo_lockfile_root()
            .is_some_and(|root| lockfile_path.parent() == Some(root.as_path()));
        let _lock = crate::lock_file::LockFile::new(&lockfile_path)
            .with_callback(|l| debug!("waiting for lock on {}", display_path(l)))
            .lock()?;

        let mut existing_lockfile = Lockfile::read(&lockfile_path)
            .unwrap_or_else(|err| handle_lockfile_read_error(err, &lockfile_path));

        // Collect all tools from all contributing configs. This starts from the
        // resolved toolset, then overlays newly installed versions because a
        // fuzzy request may still resolve through the old lockfile entry until
        // this update is written.
        let mut tool_versions_by_short: HashMap<String, Vec<ToolVersion>> = HashMap::new();
        let mut contributing_sources = 0;

        for (source, tools) in &tools_by_source {
            let Some((source_lockfile, _)) = lockfile_path_for_tool_source(config, source) else {
                continue;
            };
            if source_lockfile == lockfile_path {
                contributing_sources += 1;
                for (short, versions) in tools {
                    tool_versions_by_short
                        .entry(short.clone())
                        .or_default()
                        .extend(versions.clone());
                }
            }
        }

        trace!(
            "updating lockfile {} from {} source(s)",
            display_path(&lockfile_path),
            contributing_sources
        );

        for new_version in new_versions {
            if let Some((source_lockfile, _)) =
                lockfile_path_for_tool_source(config, new_version.request.source())
            {
                if source_lockfile != lockfile_path {
                    continue;
                }

                let versions = tool_versions_by_short
                    .entry(new_version.short().to_string())
                    .or_default();
                versions.retain(|tv| {
                    tv.ba() != new_version.ba()
                        || tv.request.version() != new_version.request.version()
                        || tv.request.source() != new_version.request.source()
                });
                versions.push(new_version.clone());
            } else if let Some(versions) = tool_versions_by_short.get_mut(new_version.short()) {
                if let Some((idx, request)) = versions
                    .iter()
                    .enumerate()
                    .exactly_one()
                    .ok()
                    .map(|(idx, tv)| (idx, tv.request.clone()))
                {
                    // Only propagate when the new install resolves the same
                    // version specifier as the config. `mise x node` (no
                    // version) is rewritten by `with_default_to_latest` to
                    // carry the config's version string, so it matches and
                    // updates the lockfile as expected. `mise x node@latest`
                    // with mise.toml `node = "24"` carries a "latest"
                    // specifier that doesn't match — that's an ad-hoc CLI
                    // override and pairing the "24" request with a 25.x
                    // install would produce a nonsensical lockfile entry.
                    if new_version.request.version() != request.version() {
                        trace!(
                            "skipping lockfile update for {}@{} in {}: CLI override does not match config request {}",
                            new_version.short(),
                            new_version.version,
                            display_path(&lockfile_path),
                            request.version(),
                        );
                        continue;
                    }
                    let mut new_version = new_version.clone();
                    new_version.request = request;
                    versions.remove(idx);
                    versions.push(new_version);
                } else {
                    trace!(
                        "skipping lockfile update for {}@{} in {}: ambiguous config entries",
                        new_version.short(),
                        new_version.version,
                        display_path(&lockfile_path)
                    );
                }
            }
        }

        let tools_by_short: HashMap<String, Vec<LockfileTool>> = tool_versions_by_short
            .iter()
            .map(|(short, versions)| {
                Ok((
                    short.clone(),
                    versions
                        .iter()
                        .map(lockfile_tool_from_tool_version)
                        .collect::<Result<Vec<_>>>()?,
                ))
            })
            .collect::<Result<_>>()?;

        // Check for provenance regression before merging (which drops old version entries).
        // For github backend tools, error if the highest prior version had provenance but
        // the new version does not — this could indicate a supply chain attack.
        // Confirmed regressions are excluded from merge to preserve the old provenance entry.
        // Unverified upgrades (already-installed versions) instead preserve the prior
        // provenance entry as a baseline for the later auto-lock pass (see #11225).
        let ProvenanceRegressionCheck {
            regressing: regressing_tools,
            errors: regression_errors,
            deferred_baselines,
        } = check_provenance_regression(&existing_lockfile, &tools_by_short);
        has_deferred_provenance |= !deferred_baselines.is_empty();
        provenance_errors.extend(regression_errors);

        // Process each tool with deduplication, skipping regressing tools
        for (short, entries) in tools_by_short {
            if regressing_tools.contains(&short) {
                continue;
            }
            let versions = &tool_versions_by_short[&short];
            let bindings = entries
                .iter()
                .flat_map(|entry| {
                    entry.specifiers.iter().map(|specifier| {
                        (
                            specifier.clone(),
                            entry.version.clone(),
                            entry.options.clone(),
                        )
                    })
                })
                .collect_vec();
            // Normal monorepo installs load only the current config hierarchy,
            // not every sibling project. Consensus among those visible requests
            // is therefore not authoritative for the shared root lockfile. Fail
            // closed there and preserve legacy entries; ordinary lockfiles can
            // safely migrate when all requests for the file agree.
            let rekey_decisions = if is_monorepo_root_lockfile {
                RekeyDecisions::new()
            } else {
                build_rekey_decisions(versions, existing_lockfile.tools.get(&short))
            };
            let (mut merged_tools, consumed_keys) = merge_tool_entries(
                entries,
                existing_lockfile.tools.get(&short),
                |version, platform| {
                    rekey_decisions
                        .get(&(version.to_string(), platform.to_key()))
                        .cloned()
                        .flatten()
                },
            );

    if !all_provenance_errors.is_empty() {
        return Err(eyre!("{}", all_provenance_errors.join("\n")));
    }

    Ok(())
}

fn deferred_provenance_resolution_error(
    existing_tools: Option<&[LockfileTool]>,
    short: &str,
    version: &str,
    backend: &str,
    platform_key: &str,
    resolution_error: &str,
) -> Option<String> {
    find_provenance_regression_baseline(existing_tools, version, backend, platform_key, None)?;
    Some(format!(
        "could not verify provenance for {short}@{version} on \
         {platform_key}: {resolution_error}\nA prior version had provenance, so \
         mise refuses to lock this upgrade without verifying it. \
         Retry once the release source is reachable."
    ))
}

