/// Strip trailing `[...]` opts from a string, e.g. `"foo[a=1]"` → `"foo"`.
pub(crate) fn strip_opts(s: &str) -> String {
    split_bracketed_opts(s)
        .map(|(name, _)| name.to_string())
        .unwrap_or_else(|| s.to_string())
}

